from __future__ import annotations

"""ArrNexus in-app documentation catalogue.

This is intentionally data-only.  The Help Centre, contextual Help button,
USER_GUIDE.md and documentation audit are all generated from the same source so
new features cannot quietly drift away from their instructions.
"""

from typing import Any


def _as_list(value):
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    return list(value)


def _topic(slug: str, title: str, category: str, summary: str, *, prerequisites=(), setup=(), usage=(), success=(), troubleshooting=(), safety=(), related=()) -> dict[str, Any]:
    return {
        "slug": slug,
        "title": title,
        "category": category,
        "summary": summary,
        "prerequisites": _as_list(prerequisites),
        "setup": _as_list(setup),
        "usage": _as_list(usage),
        "success": _as_list(success),
        "troubleshooting": _as_list(troubleshooting),
        "safety": _as_list(safety),
        "related": _as_list(related),
    }


