def topic_for_path(path: str) -> str:
    value = str(path or "/")
    for prefix, slug in ROUTE_TOPIC_PREFIXES:
        if prefix == "/":
            if value == "/":
                return slug
            continue
        if value.startswith(prefix):
            return slug
    return "getting-started"


def get_topic(slug: str | None) -> dict[str, Any] | None:
    return TOPICS_BY_SLUG.get(str(slug or ""))


def categories() -> list[tuple[str, list[dict[str, Any]]]]:
    order: list[str] = []
    grouped: dict[str, list[dict[str, Any]]] = {}
    for topic in TOPICS:
        category = topic["category"]
        if category not in grouped:
            order.append(category)
            grouped[category] = []
        grouped[category].append(topic)
    return [(name, grouped[name]) for name in order]
